import type { FC } from 'react';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import ToolLayout from '@/components/tools/ToolLayout';
import ColorInput from '@/components/tools/color-converter/ColorInput';
import ColorSwatch from '@/components/tools/color-converter/ColorSwatch';
import ResultGrid from '@/components/tools/color-converter/ResultGrid';
import { usePersistentState } from '@/hooks/usePersistentState';
import { convertAll } from '@/lib/color/convert';
import { COLOR_SPACES, COLOR_SPACE_LABELS, type ColorSpace, type ColorValueMap } from '@/lib/color/types';

const DEFAULT_RESULTS = convertAll('hex', '#3b82f6') as ColorValueMap;

const ColorConverter: FC = () => {
  const [space, setSpace] = usePersistentState<ColorSpace>('color-converter:space', 'hex');
  const [draft, setDraft] = usePersistentState<ColorValueMap[ColorSpace]>('color-converter:draft', DEFAULT_RESULTS.hex);
  const [results, setResults] = usePersistentState<ColorValueMap>('color-converter:results', DEFAULT_RESULTS);
  const [error, setError] = usePersistentState<string | null>('color-converter:error', null);

  const handleSpaceChange = (nextSpace: ColorSpace) => {
    setSpace(nextSpace);
    setDraft(results[nextSpace]);
    setError(null);
  };

  const handleDraftChange = (nextValue: ColorValueMap[ColorSpace]) => {
    setDraft(nextValue);
    const next = convertAll(space, nextValue);
    if (next) {
      setResults(next);
      setError(null);
    } else {
      setError(space === 'hex' ? 'Enter a valid hex color, e.g. #3b82f6' : 'Enter valid values for every field');
    }
  };

  return (
    <ToolLayout
      title="Color Code Generator"
      description="Pick a format, enter a color, and get it converted to HEX, RGB, HSL, LAB, LCH, OKLab, and OKLCH instantly."
    >
      {/* lg:-mb-16 cancels most of ToolLayout's trailing pb-20 below this
          page's content — this page's content is short enough it doesn't
          need that extra scroll room. */}
      <div className="grid grid-cols-1 lg:grid-cols-[1fr,1.2fr] gap-8 items-start lg:-mb-16">
        <div className="glass-panel hover:border-border p-6 md:p-8">
          <div className="flex flex-col sm:flex-row sm:items-start gap-4 mb-6">
            <ColorSwatch hex={results.hex} />
            <div className="flex-1 min-w-0">
              <label className="block text-xs font-medium text-muted-foreground mb-1.5">Convert from</label>
              <Select value={space} onValueChange={(v) => handleSpaceChange(v as ColorSpace)}>
                <SelectTrigger className="w-full sm:w-48" aria-label="Convert from">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {COLOR_SPACES.map((s) => (
                    <SelectItem key={s} value={s}>
                      {COLOR_SPACE_LABELS[s]}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <ColorInput space={space} value={draft} onChange={handleDraftChange} error={error} />
        </div>

        <div>
          <h2 className="text-sm font-medium text-muted-foreground mb-3 px-1">
            Converted values
          </h2>
          <ResultGrid results={results} />
        </div>
      </div>
    </ToolLayout>
  );
};

export default ColorConverter;
